FONT_DIR = Path("/usr/share/fonts/truetype/dejavu")


class PhotoError(ValueError):
    pass


def load_photo(data):
    if len(data) > MAX_BYTES:
        raise PhotoError("file_size")
    try:
        with Image.open(io.BytesIO(data)) as source:
            if source.format not in {"JPEG", "PNG", "WEBP"}:
                raise PhotoError("format")
            if source.width * source.height > 20_000_000:
                raise PhotoError("pixels")
            source.load()
            photo = ImageOps.exif_transpose(source).convert("RGBA")
            background = Image.new("RGBA", photo.size, "white")
            background.alpha_composite(photo)
            return background.convert("RGB")
    except PhotoError:
        raise
    except (Image.DecompressionBombError, Image.DecompressionBombWarning):
        raise PhotoError("pixels") from None
    except Exception:
        raise PhotoError("format") from None


@lru_cache(maxsize=1)
def face_detector():
    path = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
    detector = cv2.CascadeClassifier(path)
    if detector.empty():
        raise RuntimeError("Face detector unavailable")
    return detector


def inspect(photo, category="universal"):
    """Conservative initial heuristics. Manual preview remains essential."""
    issues = []
    if min(photo.size) < 600:
        issues.append("resolution")
    scale = min(1, 1000 / max(photo.size))
    reduced = photo.resize((round(photo.width * scale), round(photo.height * scale)))
    gray = cv2.cvtColor(np.array(reduced), cv2.COLOR_RGB2GRAY)
    if gray.mean() < 35 or gray.mean() > 245:
        issues.append("light")
    if cv2.Laplacian(gray, cv2.CV_64F).var() < 25:
        issues.append("blur")
    portrait = category in {"women", "men", "children", "grandchildren", "grandparents"}
    group = category in {"family", "couples"}
    faces = []
    if portrait or group:
        faces = face_detector().detectMultiScale(
            gray, scaleFactor=1.1, minNeighbors=6, minSize=(45, 45)
        )
        if len(faces) == 0:
            issues.append("face_missing")
        elif portrait and len(faces) != 1:
            issues.append("face_count")
        elif min(min(w, h) / scale for x, y, w, h in faces) < 100:
            issues.append("face_small")
        elif any(cv2.Laplacian(gray[y:y+h, x:x+w], cv2.CV_64F).var() < 20
                 for x, y, w, h in faces):
            issues.append("face_blur")
    return issues, len(faces)


@lru_cache(maxsize=96)
def font(size, bold=False):
    filename = "DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf"
    return ImageFont.truetype(str(FONT_DIR / filename), size)


def wrap(draw, text, selected_font, max_width):
    lines = []
    for paragraph in text.splitlines() or [""]:
        line = ""
        for word in paragraph.split():
            candidate = (line + " " + word).strip()
            if draw.textlength(candidate, font=selected_font) <= max_width:
                line = candidate
                continue
            if line:
                lines.append(line)
            line = ""
            for character in word:
                if draw.textlength(line + character, font=selected_font) > max_width:
                    lines.append(line)
                    line = ""
                line += character
        lines.append(line)
    return lines


def text_block(image, text, box, maximum, minimum, color, bold=False):
    draw = ImageDraw.Draw(image)
    x, y, width, height = box
    for size in range(maximum, minimum - 1, -1):
        selected_font = font(size, bold)
        lines = wrap(draw, text, selected_font, width)
        line_height = size + 10
        if len(lines) * line_height <= height:
            break
    else:
        raise PhotoError("text_long")
    top = y + (height - len(lines) * line_height) / 2
    for index, line in enumerate(lines):
        draw.text((x + width / 2, top + index * line_height), line,
                  font=selected_font, fill=color, anchor="mt")


@lru_cache(maxsize=8)
def background(template_id):
    template = THEMES[template_id]
    with Image.open(ROOT / template["background"]) as source:
        return ImageOps.fit(source.convert("RGB"), (W, H))


def photo_placement(photo, template_id, size=100, horizontal=50, vertical=50):
    x, y, width, height = THEMES[template_id]["photo"]
    target = (max(1, round(width * size / 100)), max(1, round(height * size / 100)))
    fitted = ImageOps.contain(photo.convert("RGB"), target, Image.Resampling.LANCZOS)
    left = x + round((width - fitted.width) * horizontal / 100)
    top = y + round((height - fitted.height) * vertical / 100)
    return fitted, left, top


def render(photo, theme, title, message, name="", size=100, horizontal=50, vertical=50):
    template = THEMES[theme]
    card = background(theme).copy()
    draw = ImageDraw.Draw(card)
    fitted, left, top = photo_placement(photo, theme, size, horizontal, vertical)
    right = left + fitted.width - 1
    bottom = top + fitted.height - 1
    draw.rounded_rectangle((left-6, top-6, right+6, bottom+6),
                           radius=6, fill=template["accent"])
    card.paste(fitted, (left, top))
    # Panels ensure readable, independent text on every artwork.
    for key in ("heading", "text"):
        tx, ty, tw, th = template[key]
        draw.rounded_rectangle((tx-14, ty-8, tx+tw+14, ty+th+8),
                               radius=18, fill=template["mat"])
    text_block(card, title, template["heading"], 54, 26, template["accent"], True)
    tx, ty, tw, th = template["text"]
    if name:
        text_block(card, name, (tx, ty, tw, 90), 40, 20, template["accent"], True)
        ty += 100
        th -= 100
    text_block(card, message, (tx, ty, tw, th), 36, 22, template["ink"])
    return card


def encode_image(card, image_format):
    output = io.BytesIO()
    card.save(output, format=image_format, **({"quality": 95} if image_format == "JPEG" else {}))
    return output.getvalue()


def animate(card, template_id="gold"):
    template = THEMES[template_id]
    rng = random.Random(75)
    particles = [(rng.randrange(W), rng.randrange(H), rng.uniform(20, 65), rng.randrange(2, 6))
                 for _ in range(70)]
    with tempfile.TemporaryDirectory(prefix="magic-greetings-") as directory:
        output = Path(directory) / "greeting.mp4"
        command = [
            imageio_ffmpeg.get_ffmpeg_exe(), "-y", "-f", "rawvideo", "-pix_fmt", "rgb24",
            "-s", f"{W}x{H}", "-r", "24", "-i", "-", "-an", "-c:v", "libx264",
            "-threads", "2", "-preset", "fast", "-crf", "21", "-pix_fmt", "yuv420p",
            "-movflags", "+faststart", str(output)
        ]
        with tempfile.TemporaryFile() as error_log:
            process = subprocess.Popen(command, stdin=subprocess.PIPE, stderr=error_log)
            try:
                for frame_number in range(144):
                    frame = card.copy()
                    time = frame_number / 24
                    if time < 0.8:
                        for key in ("heading", "text"):
                            tx, ty, tw, th = template[key]
                            bounds = (tx, ty, tx+tw, ty+th)
                            blank = Image.new("RGB", (tw, th), template["mat"])
                            frame.paste(Image.blend(blank, card.crop(bounds), time / 0.8), (tx, ty))
                    draw = ImageDraw.Draw(frame)
                    for px, py, speed, radius in particles:
                        yy = (py + speed * time) % H
                        xx = px + 10 * math.sin(time + px)
                        # Restrict all effects to the outer margins.
                        if 90 < xx < 990:
                            continue
                        light = round(205 + 50 * math.sin(time * 3 + py) ** 2)
                        draw.ellipse((xx-radius, yy-radius, xx+radius, yy+radius),
                                     fill=(light, light, min(255, light+10)))
                        if frame_number % 24 < 12:
                            draw.line((xx-5, yy, xx+5, yy), fill=template["accent"])
                    process.stdin.write(frame.tobytes())
                process.stdin.close()
                if process.wait(timeout=90) != 0:
                    raise RuntimeError("Video encoding failed")
                return output.read_bytes()
            finally:
                if process.poll() is None:
                    process.kill()
                    process.wait()



IDENTITY_RULES = (
    "Identity is the primary requirement. Preserve each person's individual eye shape and spacing, "
    "nose, lips, jawline, chin, facial proportions, natural asymmetry, age, skin tone and texture. "
    "Preserve glasses, hairline, expression and gaze. No beautification, age reduction, face slimming, "
    "eye enlargement, generic face substitution or exaggerated smoothing. Keep natural head-to-body "
    "proportions. Preserve the source head orientation whenever possible. "
)


def _request_scene(image, editable, prompt, api_key, reference=None, face_reference=None):
    files = [("image[]", ("scene.png", encode_image(image, "PNG"), "image/png"))]
    if reference is not None:
        files.append(("image[]", ("original-photo.png", encode_image(reference, "PNG"), "image/png")))
    if face_reference is not None:
        files.append(("image[]", ("original-face.png", encode_image(face_reference, "PNG"), "image/png")))
    if editable is not None:
        mask = Image.new("RGBA", image.size, (0, 0, 0, 255))
        mask.putalpha(ImageOps.invert(editable))
        files.append(("mask", ("edit-mask.png", encode_image(mask, "PNG"), "image/png")))
    response = requests.post(
        "https://api.openai.com/v1/images/edits",
        headers={"Authorization": f"Bearer {api_key}"},
        data={
            "model": os.environ.get("MAGIC_GREETING_IMAGE_MODEL", "gpt-image-2.6-sunburst"),
            "prompt": IDENTITY_RULES + prompt,
            "size": f"{image.width}x{image.height}",
        },
        files=files,
        timeout=(10, 240),
    )
    response.raise_for_status()
    result = base64.b64decode(response.json()["data"][0]["b64_json"], validate=True)
    with Image.open(BytesIO(result)) as candidate:
        if candidate.size != image.size:
            raise ValueError("Unexpected image dimensions")
        edited = candidate.convert("RGB")
        if editable is None:
            return edited
        # Keep protected pixels from the original even if the provider altered them.
        return Image.composite(edited, image, editable)


@st.cache_resource
def scene_request_pool():
    return ThreadPoolExecutor(max_workers=2, thread_name_prefix="magic-image")


def edit_scene(image, editable, prompt, api_key, reference=None, face_reference=None):
    # Limit the entire wait and retain jobs so retries do not duplicate API calls.
    fingerprint = hashlib.sha256(prompt.encode())
    for source in (image, editable, reference, face_reference):
        if source is not None:
            fingerprint.update(str((source.mode, source.size)).encode())
            fingerprint.update(source.tobytes())
    signature = fingerprint.hexdigest()
    pending = st.session_state.get("scene_pending_request")
    if pending and pending["signature"] != signature:
        if not pending["future"].done():
            raise requests.Timeout("Previous image request is still running")
        st.session_state.pop("scene_pending_request", None)
        pending = None
    if pending is None:
        future = scene_request_pool().submit(
            _request_scene, image.copy(), editable.copy() if editable is not None else None,
            prompt, api_key, reference.copy() if reference is not None else None,
            face_reference.copy() if face_reference is not None else None)
        pending = {"signature": signature, "future": future}
        st.session_state["scene_pending_request"] = pending
    try:
        result = pending["future"].result(timeout=240)
    except FutureTimeout as error:
        raise requests.Timeout("Image request exceeded the UI wait limit") from error
    except Exception:
        st.session_state.pop("scene_pending_request", None)
        raise
    st.session_state.pop("scene_pending_request", None)
    return result


@contextmanager
def generation_status(russian):
    label = "Создаём вашу открытку…" if russian else "Creating your card…"
    with st.status(label, expanded=True) as status:
        st.write("Генерация может занять несколько минут. Общее ожидание ограничено 4 минутами."
                 if russian else
                 "Generation can take a few minutes. The total wait is limited to 4 minutes.")
        st.caption("Не закрывайте и не обновляйте вкладку. Повторно нажимать кнопку не нужно. "
                   "Ниже отображается время ожидания; при ошибке появится сообщение."
                   if russian else
                   "Keep this tab open without refreshing. You do not need to click again. "
                   "Elapsed time is shown below; an error message will appear if the request fails.")
        try:
            with st.spinner("Ожидаем изображение от сервиса…" if russian else
                            "Waiting for the image service…", show_time=True):
                yield
        except Exception:
            status.update(label="Создание не завершилось — см. сообщение ниже." if russian else
                          "Creation did not finish — see the message below.", state="error", expanded=True)
            raise
        else:
            status.update(label="Изображение получено. Готовим открытку." if russian else
                          "Image received. Preparing your card.", state="complete", expanded=False)


def scene_input(photo, market=False):
    ratio = photo.width / photo.height
    size = (1536, 1024) if ratio > 1.2 else (1024, 1536) if ratio < .83 else (1024, 1024)
    if market:
        size = (1536, 1024)
    fitted = ImageOps.contain(photo, (round(size[0] * .82), round(size[1] * .68)),
                              Image.Resampling.LANCZOS)
    canvas = Image.new("RGB", size, "#263229")
    canvas.paste(fitted, ((size[0] - fitted.width) // 2, round(size[1] * .05)))
    return canvas


def scene_editable(size, faces, selected=None):
    editable = Image.new("L", size, 255 if selected is None else 0)
    draw = ImageDraw.Draw(editable)
    for index, (x, y, w, h) in enumerate(faces):
        if selected is None or selected == index:
            draw.ellipse((x - w*.14, y - h*.24, x + w*1.14, y + h*1.12),
                         fill=0 if selected is None else 255)
            if selected is None:
                draw.rectangle((x, y, x + w, y + h), fill=0)
    if selected is not None:
        editable = editable.filter(ImageFilter.GaussianBlur(5))
        draw = ImageDraw.Draw(editable)
        for index, (x, y, w, h) in enumerate(faces):
            if index != selected:
                draw.rectangle((x - 10, y - 12, x + w + 10, y + h + 12), fill=0)
    return editable


def detect_scene_faces(image):
    gray = cv2.cvtColor(np.asarray(image), cv2.COLOR_RGB2GRAY)
    return sorted(tuple(map(int, face)) for face in face_detector().detectMultiScale(
        gray, scaleFactor=1.1, minNeighbors=5, minSize=(55, 55)
    ))


def scene_editor(photo, digest, scene, lang, title, message, name, api_key, t):
    ru = lang == "ru"
    market = scene == "market"
    digest = f"{digest}_{scene}_identity_v2"
    if st.session_state.get("scene_digest") != digest:
        canvas = scene_input(photo, market)
        faces = detect_scene_faces(canvas)
        issues, _ = inspect(photo, "family")
        saved = st.session_state.setdefault("scene_saved", {}).get(digest, {})
        st.session_state.update(scene_digest=digest, scene_source=canvas, scene_faces=faces,
                                scene_issues=issues, scene_versions=saved.get("versions", []),
                                scene_confirmed_faces=saved.get("faces", []),
                                scene_original_faces=saved.get("original_faces", []))
    canvas = st.session_state["scene_source"]
    faces = st.session_state["scene_faces"]
    versions = st.session_state["scene_versions"]
    if st.session_state["scene_issues"] or not faces:
        issues = set(st.session_state["scene_issues"])
        reasons = []
        if issues & {"blur", "face_blur"}:
            reasons.append("снимок или лицо недостаточно резкие" if ru else
                           "the photo or a face is not sharp enough")
        if "resolution" in issues:
            reasons.append("слишком маленький размер снимка" if ru else
                           "the image resolution is too low")
        if "light" in issues:
            reasons.append("снимок слишком тёмный или пересвечен" if ru else
                           "the photo is too dark or overexposed")
        if "face_missing" in issues or not faces:
            reasons.append("не удалось уверенно найти лица" if ru else
                           "faces could not be detected reliably")
        if "face_small" in issues:
            reasons.append("лица слишком мелкие на снимке" if ru else
                           "faces are too small in the photo")
        if "face_count" in issues:
            reasons.append("проверьте количество людей на снимке" if ru else
                           "check the number of people in the photo")
        details = "; ".join(reasons) or ("проверьте качество фото" if ru else "check the photo quality")
        st.warning(("**Генерация ещё не началась.** Нужно заменить фото: " + details +
                    ". Загрузите более чёткий оригинал в блоке «2. Загрузите фотографию» выше. "
                    "За этот шаг запрос на генерацию не отправлялся.")
                   if ru else
                   ("**Generation has not started.** Please replace this photo: " + details +
                    ". Upload a clearer original in section 2 above. "
                    "No generation request was sent at this step."))
        return
    if not versions:
        st.markdown("**Проверьте найденные лица**" if ru else "**Check detected faces**")
        st.caption("Снимите галочку с лишних отметок." if ru else "Uncheck any false detections.")
        selected_faces = []
        columns = st.columns(min(5, len(faces)))
        for index, box in enumerate(faces):
            x, y, w, h = box
            with columns[index % len(columns)]:
                st.image(canvas.crop((x, y, x + w, y + h)), width=80)
                if st.checkbox(f"Лицо {index + 1}" if ru else f"Face {index + 1}",
                               value=True, key=f"scene_face_{digest}_{index}"):
                    selected_faces.append(box)
        if market and len(selected_faces) != 2:
            st.info("Для ярмарки отметьте два лица." if ru else "Select two faces for the Christmas market.")
            return
        if not 1 <= len(selected_faces) <= 5:
            st.warning("Выберите от одного до пяти лиц." if ru else "Select one to five faces.")
            return
        faces = selected_faces
    else:
        faces = st.session_state["scene_confirmed_faces"]
    if not versions and st.button(t["create"], type="primary"):
        with generation_status(ru):
            if market:
                prompt = (
                    "Create a realistic wide holiday photograph of exactly the two foreground adults "
                    "in the reference photo, seated at opposite sides of one wooden table with two mugs "
                    "at an evening Christmas market. Preserve their left-to-right order, facial structure, "
                    "age, expressions, glasses and hair. Both look toward camera with natural head angles. "
                    "Complete heads, generous headroom, winter coats, natural proportions. "
                    "Compose both people in the upper 72 percent of the image. Reserve the lower "
                    "24 percent for a short greeting: an uncluttered softly lit wooden tabletop "
                    "with no hands, faces, mugs, gifts or busy decorations in that lower text zone. "
                    "The scene must continue naturally into that area. No text or frames."
                )
                edit_mask = None
            else:
                setting = {
                    "ornament": "a cozy room with a lit Christmas tree, glass ornaments and burgundy ribbons",
                    "forest": "a magical snowy fir forest with warm Christmas fairy lights and subtle lanterns",
                    "city": "a festive evening city street with Christmas lights, a lit tree and snowy rooftops",
                    "fireplace": "a cozy Christmas living room with a glowing fireplace, decorated tree and gifts",
                    'panorama': 'a festive balcony above a winter city with snowy rooftops, a lit riverfront and Christmas garlands',
                    'fireworks': 'an elegant outdoor New Year scene with a riverfront city skyline and golden fireworks',
                    'lantern': 'a snowy Christmas forest with warm candle lanterns, decorated fir branches and glass ornaments',
                    'snow': 'a snowy fir forest in soft winter daylight with festive decorations',
                    'morning': 'a bright Christmas morning room with a festive breakfast table and a tree',
                }[scene]
                prompt = (
                    "Transform the setting around these people into " + setting + ". "
                    "Use festive knits indoors and elegant warm coats outdoors. Preserve people, "
                    "poses, scale and positions. Keep protected faces, glasses, expressions and lighting. "
                    "Leave the added space above and around people filled with the setting. "
                    "Reserve the lower 24 percent as a calm, uncluttered part of this same setting "
                    "for a short greeting. Keep faces, hands, gifts, decorations and other focal "
                    "objects out of that lower area. Use softly lit snow outdoors, or a softly "
                    "lit rug or tabletop indoors, with low visual detail and even lighting. "
                    "Do not draw a separate banner, frame, panel or text."
                )
                edit_mask = scene_editable(canvas.size, faces)
            result = edit_scene(canvas, edit_mask, prompt, api_key, reference=photo)
        st.session_state["scene_original_faces"] = list(faces)
        st.session_state["scene_confirmed_faces"] = detect_scene_faces(result) if market else faces
        versions.append(result)
        st.session_state["scene_saved"][digest] = {
            "versions": versions, "faces": st.session_state["scene_confirmed_faces"],
            "original_faces": st.session_state["scene_original_faces"]
        }
        st.rerun()
    if not versions:
        return
    left, right = st.columns(2)
    original_preview = photo.copy()
    original_preview.thumbnail((600, 440), Image.Resampling.LANCZOS)
    left.image(original_preview, caption="Исходное фото" if ru else "Original photo")
    version = st.selectbox("Версия" if ru else "Version", list(range(len(versions))),
                           index=len(versions) - 1, format_func=lambda value: str(value + 1),
                           key=f"scene_version_{digest}_{len(versions)}")
    current = versions[version]
    can_refine = (len(faces) == len(st.session_state["scene_original_faces"])
                  and bool(faces))
    if can_refine and len(versions) < 4:
        with st.expander("Поправить одно лицо" if ru else "Refine one face"):
            choices = []
            for index, (x, y, w, h) in enumerate(faces):
                choices.append(index)
                st.image(current.crop((x, y, x + w, y + h)), caption=str(index + 1), width=85)
            choice = st.selectbox("Лицо" if ru else "Face", choices,
                                  format_func=lambda value: str(value + 1))
            note = st.text_area("Что поправить?" if ru else "What should change?", max_chars=300)
            if st.button("Применить правку" if ru else "Apply refinement", disabled=not note.strip()):
                with generation_status(ru):
                    x, y, w, h = st.session_state["scene_original_faces"][choice]
                    face_reference = canvas.crop((max(0, x-20), max(0, y-20),
                                                  min(canvas.width, x+w+20),
                                                  min(canvas.height, y+h+20)))
                    versions.append(edit_scene(
                        current, scene_editable(current.size, faces, choice),
                        "Edit only the selected face in the FIRST image. The SECOND image is the "
                        "original customer photo; the THIRD image isolates this person's original face. "
                        "Use those originals as the identity reference. Preserve the first image's "
                        "composition and other people. Restore the person's original facial features "
                        "and expression. Apply this localized request only: " + note,
                        api_key, reference=photo, face_reference=face_reference))
                st.rerun()
    if can_refine:
        st.caption(f"Корректировок осталось: {4-len(versions)}" if ru else
                   f"Refinements left: {4-len(versions)}")
    else:
        st.caption("Локальная правка доступна, когда в результате найдены оба лица." if ru else
                   "Local refinements require both faces to be detected in the result.")
    with st.expander("Сравнить лица крупно" if ru else "Compare faces close up"):
        source_faces = st.session_state["scene_original_faces"]
        for index, (source_box, result_box) in enumerate(zip(source_faces, faces)):
            source_x, source_y, source_w, source_h = source_box
            x, y, w, h = result_box
            source_column, result_column = st.columns(2)
            source_column.image(canvas.crop((source_x, source_y, source_x+source_w, source_y+source_h)),
                                caption=("Исходное лицо " if ru else "Original face ") + str(index+1),
                                width=180)
            result_column.image(current.crop((x, y, x+w, y+h)),
                                caption=("Результат " if ru else "Result ") + str(index+1), width=180)
    st.caption("Проверьте сходство каждого человека перед скачиванием." if ru else
               "Please check each person's likeness before downloading.")
    card = render_original(current, "gold", title, message, name, christmas=True,
                           greeting_reserved=True)
    preview = card.copy()
    preview.thumbnail((600, 440), Image.Resampling.LANCZOS)
    right.image(preview, caption=t["preview"])
    st.download_button(t["download"] + " PNG", encode_image(card, "PNG"),
                       "Magic_Greetings_Christmas_Market.png" if market else
                       f"Magic_Greetings_{scene}.png", "image/png", on_click="ignore")


