def runtime_setting(name):
    try:
        return str(st.secrets.get(name) or os.environ.get(name, ""))
    except FileNotFoundError:
        return os.environ.get(name, "")


SCENE_EXAMPLES = {'ornament': '', 'forest': '', 'city': '', 'fireplace': '', 'morning': '', 'snow': '', 'lantern': '', 'fireworks': '', 'panorama': ''}
GOLD_BACKGROUND = ''
def render_frame(photo, theme, title, message, name="", size=100, horizontal=50, vertical=50):
    template = THEMES[theme]
    card = background(theme).copy()
    if theme == "gold":
        with Image.open(BytesIO(base64.b64decode(GOLD_BACKGROUND))) as artwork:
            card = ImageOps.fit(artwork.convert("RGB"), card.size)
    fitted, left, top = photo_placement(photo, theme, size, horizontal, vertical)
    card.paste(fitted, (left, top))
    overlay = Image.new("RGBA", card.size, (0, 0, 0, 0))
    draw = ImageDraw.Draw(overlay)
    for key, value in (("heading", title), ("text", name + message)):
        if value.strip():
            x, y, w, h = template[key]
            draw.rounded_rectangle((x-14, y-8, x+w+14, y+h+8), radius=18, fill=(255, 255, 255, 26))
    card = Image.alpha_composite(card.convert("RGBA"), overlay).convert("RGB")
    ink = "#253342" if theme == "winter" else "#462b17"
    text_block(card, title, template["heading"], 54, 26, ink, True)
    tx, ty, tw, th = template["text"]
    if name:
        text_block(card, name, (tx, ty, tw, 90), 40, 20, ink, True)
        ty += 100
        th -= 100
    text_block(card, message, (tx, ty, tw, th), 36, 22, ink)
    return card


@st.cache_data(show_spinner=False)
def frame_example(theme):
    sample = Image.new("RGB", (640, 480), "#eee5d7")
